36	        indisponivel ? 'border-[#E4E4E7] opacity-60' : 'border-[#E4E4E7] hover:shadow-md hover:border-[#FF441F]/20'
37	      }`}
38	    >
39	      <div className="flex-1 flex flex-col justify-between min-w-0">
