60	              {temPromo && <span className="text-[10px] bg-green-100 text-green-700 px-1.5 py-0.5 rounded font-bold">PROMO</span>}
61	            </div>
62	          </div>
63	
64	          {somenteVitrine ? null : !indisponivel ? (
